 471→// createWorktree creates a git worktree using native git command
 472→func createWorktree(repoDir, worktreeDir, branch string) error {
 473→	cmd := exec.CommandContext(context.Background(), "git", "worktree", "add", worktreeDir, "-b", branch)
 474→	cmd.Dir = repoDir
 475→	return cmd.Run()
 476→}
