 871→			localEmail: "local@example.com",
 872→			wantName:   "Local User",
 873→			wantEmail:  "local@example.com",
 874→		},
 875→		{
 876→			name:        "only name set locally falls back to global for email",
 877→			localName:   "Local User",
 878→			globalEmail: "global@example.com",
 879→			wantName:    "Local User",
 880→			wantEmail:   "global@example.com",
 881→		},
 882→		{
 883→			name:       "only email set locally falls back to global for name",
 884→			localEmail: "local@example.com",
 885→			globalName: "Global User",
 886→			wantName:   "Global User",
 887→			wantEmail:  "local@example.com",
 888→		},
 889→		{
 890→			name:        "nothing set locally falls back to global for both",
 891→			globalName:  "Global User",
 892→			globalEmail: "global@example.com",
 893→			wantName:    "Global User",
 894→			wantEmail:   "global@example.com",
 895→		},
 896→		{
 897→			name:      "nothing set anywhere returns defaults",
 898→			wantName:  "Unknown",
 899→			wantEmail: "unknown@local",
 900→		},
 901→		{
 902→			name:        "local takes precedence over global",
 903→			localName:   "Local User",
 904→			localEmail:  "local@example.com",
 905→			globalName:  "Global User",
 906→			globalEmail: "global@example.com",
 907→			wantName:    "Local User",
 908→			wantEmail:   "local@example.com",
 909→		},
 910→	}
 911→
 912→	for _, tt := range tests {
