 995→// initBareWithMetadataBranch creates a bare repo with a main branch and an
 996→// entire/checkpoints/v1 branch containing checkpoint data via git CLI.
 997→func initBareWithMetadataBranch(t *testing.T) string {
 998→	t.Helper()
 999→	bareDir := t.TempDir()
1000→
1001→	// Init bare, create main branch with a commit
1002→	workDir := t.TempDir()
1003→	run := func(dir string, args ...string) {
1004→		cmd := exec.CommandContext(context.Background(), "git", args...)
1005→		cmd.Dir = dir
1006→		if out, err := cmd.CombinedOutput(); err != nil {
1007→			t.Fatalf("git %v failed: %v\n%s", args, err, out)
1008→		}
1009→	}
1010→	run(bareDir, "init", "--bare", "-b", "main")
1011→	run(workDir, "clone", bareDir, ".")
1012→	run(workDir, "config", "user.email", "test@test.com")
1013→	run(workDir, "config", "user.name", "Test User")
1014→	if err := os.WriteFile(filepath.Join(workDir, "README.md"), []byte("# Test"), 0o644); err != nil {
1015→		t.Fatalf("failed to write file: %v", err)
1016→	}
1017→	run(workDir, "add", ".")
1018→	run(workDir, "commit", "-m", "init")
1019→	run(workDir, "push", "origin", "main")
1020→
1021→	// Create orphan entire/checkpoints/v1 with data
1022→	run(workDir, "checkout", "--orphan", paths.MetadataBranchName)
1023→	run(workDir, "rm", "-rf", ".")
1024→	if err := os.WriteFile(filepath.Join(workDir, "metadata.json"), []byte(`{"checkpoint_id":"test123"}`), 0o644); err != nil {
1025→		t.Fatalf("failed to write file: %v", err)
1026→	}
1027→	run(workDir, "add", ".")
1028→	run(workDir, "commit", "-m", "Checkpoint: test123")
1029→	run(workDir, "push", "origin", paths.MetadataBranchName)
1030→
1031→	return bareDir
1032→}
